									<div class="description">
										<p>
											The Caniprof Refuge app makes it easier and faster for dogs to be adopted!
											Create your Refuge today on the app, and start listing the dogs arriving at
											your shelter.<br />
											Thanks to its simple design, it takes just a few seconds for a shelter to
											create a new card each time a dog is recovered. This displays the dog's
											photo, key information, and shelter contact details for anyone interesting
											in adopting. </p>
