										<p>
											You are going to spend the day at the beach and you don't know what to do
											with your equipment?<br />
											You don't want to have your leather on your shoulder to visit a charming
											village?<br />
											Your helmet is worth 400euro and it hurts your heart to leave it attached to
											your motorcycle in direct sunlight?<br />
											My guardian will tell you, via this application, the place where it is
											possible to put your equipment away! </p>
