									<div class="description">
										<p>
											The concept of dental tourism – visiting another country to access cheaper
											dental work – is nothing new. But many Brits become frustrated researching
											their options because there are just so many clinics to choose from, and it
											can be hard to know which are really reputable.<br />
											Dentaly Go aims to make this process easier and less stressful for you. </p>
